            .community-panel { padding:27px 18px; }

            .about-section { padding: 34px 18px 58px; gap: 10px; }

            .about-copy { padding: 8px 0; border-radius: 0; background: transparent; box-shadow: none; border: 0; }

            .about-slider-arrow { width: 34px; height: 34px; font-size: 20px; }

            .about-slider-arrow.prev { left: 8px; }

            .about-slider-arrow.next { right: 8px; }

