            .about-signoff { font-size: 13px; }

        }

        .join-section {

            background: linear-gradient(135deg, #ffe1eb 0%, #ffe9df 100%);

            text-align: center;

            padding: 42px 7%;

        }

        .join-panel {

            max-width: 900px;

            margin: auto;

            padding: 32px 28px;

            border-radius: 26px;

            background: white;

            position: relative;

            box-shadow: 0 12px 28px rgba(18, 53, 107, .08);

        }

        .join-panel .section-kicker { margin-bottom: 9px; }

        .join-panel .section-title {

            max-width: 650px;

            margin: 0 auto 10px;

            font-size: clamp(30px, 3.4vw, 42px);

        }

        .join-panel .section-lead {

