            box-shadow: 0 5px 0 #082044;

        }

        .join-button span { color: var(--yellow); font-size: 22px; }

        /* ================= FOOTER BERTAUT ================= */
        .site-footer {
            position: relative;
            overflow: hidden;
            padding: 58px 7% 22px;
            background: linear-gradient(125deg, #102f60 0%, #173f7c 52%, #12356b 100%);
            border-top: 5px solid #ffd447;
            color: #fff;
            font-size: 13px;
            line-height: 1.75;
        }

        .site-footer::before,
        .site-footer::after {
            content: "";
            position: absolute;
            border-radius: 50%;
            pointer-events: none;
        }

        .site-footer::before {
            width: 230px;
            height: 230px;
            top: -145px;
            right: 8%;
            border: 24px solid rgba(255,255,255,.055);
        }

        .site-footer::after {
            width: 150px;
            height: 150px;
            bottom: -105px;
            left: 34%;
            background: rgba(255,212,71,.07);
        }

        .footer-inner {
            position: relative;
            z-index: 1;
            width: min(1180px, 100%);
            margin: 0 auto;
        }

        .footer-main {
            display: grid;
            grid-template-columns: 1.5fr 1fr 1fr;
            gap: clamp(28px, 5vw, 76px);
            padding-bottom: 38px;
        }

        .footer-brand strong {
            display: inline-block;
            margin-bottom: 12px;
            color: #fff;
            font: 800 39px/1 'Baloo 2', cursive;
            letter-spacing: .2px;
        }

        .footer-brand p {
            max-width: 390px;
            color: #dce9ff;
            font-size: 13px;
            line-height: 1.9;
        }

        .footer-tagline {
            display: inline-flex;
            align-items: center;
            gap: 7px;
            margin-top: 17px;
            padding: 7px 13px;
            border: 1px solid rgba(255,212,71,.45);
            border-radius: 999px;
            background: rgba(255,212,71,.10);
            color: #ffe17a;
            font-size: 11px;
            font-weight: 700;
        }

        .footer-column h3 {
            margin: 5px 0 15px;
            color: #ffdc61;
            font: 800 19px 'Baloo 2', cursive;
        }

        .footer-column p {
            max-width: 300px;
            color: #dce9ff;
            font-size: 12px;
            line-height: 1.85;
        }

        .footer-links {
            display: grid;
            gap: 9px;
        }

        .footer-links a {
            width: fit-content;
            color: #eaf2ff;
            font-size: 12px;
            text-decoration: none;
            transition: color .2s ease, transform .2s ease;
        }

        .footer-links a:hover {
            color: #ffdc61;
            transform: translateX(4px);
        }

        .footer-cta {
            display: inline-flex;
            align-items: center;
            gap: 10px;
            margin-top: 16px;
            padding: 10px 17px;
            border-radius: 999px;
