            background: #ffe47d;
        }

        .footer-bottom {
            display: flex;
            align-items: center;
            justify-content: space-between;
            gap: 16px;
            padding-top: 18px;
            border-top: 1px solid rgba(255,255,255,.18);
            color: #dce9ff;
            font-size: 11px;
        }

        .footer-bottom .footer-motto {
            color: #fff;
            font-weight: 600;
        }

        @media (max-width: 850px) {

