            .footer-column h3 { margin-bottom: 9px; }
            .footer-cta { margin-top: 12px; }

            .feature-grid { grid-template-columns: 1fr; }

            .feature-card { min-height: auto; }

            .activity-grid { grid-template-columns: 1fr; max-width: 380px; }

            .join-panel { padding: 38px 18px; }

        }

    

        /* ================= LATAR PASTEL BERTAUT =================
           Seluruh halaman mengikuti warna hero: putih krem, biru muda,
           dan aksen pastel biru/kuning/pink yang lembut. Slideshow foto
           "Kenali Bertaut" tetap memakai latar foto aslinya.
        ================================================================== */
        html {
            background: #fffdf8;
        }

        body {
            position: relative;
            isolation: isolate;
            height: auto;
            min-height: 100%;
            background: transparent;
        }

        /* Satu latar berkesinambungan dari awal sampai akhir halaman. */
        body::before {
            content: "";
            position: absolute;
            inset: 0;
            z-index: -1;
            pointer-events: none;
            background-image:
                radial-gradient(circle at 8% 12%, rgba(255, 211, 66, .18) 0 82px, transparent 84px),
                radial-gradient(circle at 96% 29%, rgba(91, 159, 244, .14) 0 92px, transparent 94px),
                radial-gradient(circle at 3% 53%, transparent 0 48px, rgba(91, 159, 244, .12) 49px 62px, transparent 63px 78px, rgba(255, 211, 66, .09) 79px 91px, transparent 92px),
                radial-gradient(circle at 94% 76%, rgba(91, 159, 244, .13) 0 108px, transparent 110px),
                radial-gradient(circle at 12% 94%, rgba(255, 190, 211, .12) 0 62px, transparent 64px),
                linear-gradient(180deg, #fffdf8 0%, #f1f6ff 27%, #f8fbff 52%, #eef5ff 76%, #fffdf8 100%);
            background-repeat: no-repeat;
            background-size: 100% 100%;
        }

        /* Semua bagian mengikuti latar global, kecuali slideshow foto. */
        .hero,
        .landing-section:not(.about-section),
        .features-section,
        .activity-section,
        .why-section,
        .category-section,
        .how-section,
        .impact-section,
        .community-section,
        .faq-section,
        .join-section {
            background: transparent !important;
            background-image: none !important;
        }

        /* Hindari ornamen latar section yang saling menimpa. */
        .features-section::before,
        .features-section::after {
            display: none !important;
        }

        .activity-section::before {
            background: transparent !important;
        }

        /* Slideshow foto "Kenali Bertaut" tidak diubah. */
        .about-section {
            background: transparent;
            background-image: none;
        }

        /* Pastikan judul dan deskripsi tetap kontras di atas latar pastel. */
        .landing-section:not(.about-section) .section-title {
            color: #12356b;
        }

        .landing-section:not(.about-section) .section-lead,
        .landing-section:not(.about-section) .activity-note {
            color: #526b8e;
        }

        /* Label berada di tengah area gabungan foto dan teks, bukan di atas kolom teks saja. */
        .impact-section > div:last-child > .section-kicker {
            position: absolute;
            top: 38px;
            left: 50%;
            transform: translateX(-50%);
            display: inline-flex;
            align-items: center;
            justify-content: center;
            width: max-content;
            max-width: calc(100% - 36px);
            margin: 0;
            text-align: center;
            z-index: 2;
        }

        @media (max-width: 850px) {
            .impact-section {
                padding-top: 100px;
            }
            .impact-section > div:last-child > .section-kicker {
                top: 30px;
            }
        }

        /* Panel ajakan dan kartu tetap mempertahankan permukaan putihnya. */
        .feature-card,
        .why-card,
        .category-item,
        .faq-item,
        .step-card,
        .community-panel,
        .join-panel {
            position: relative;
            z-index: 1;
        }

    

        /* ================= ANIMASI MUNCUL SAAT DI-SCROLL ================= */
        .scroll-reveal {
            opacity: 0;
            transform: translateY(30px);
            transition:
                opacity .75s ease,
                transform .75s cubic-bezier(.2, .7, .2, 1);
            transition-delay: var(--reveal-delay, 0ms);
            will-change: opacity, transform;
        }

        .scroll-reveal.is-visible {
            opacity: 1;
            transform: translateY(0);
        }

        @media (prefers-reduced-motion: reduce) {
            .scroll-reveal {
                opacity: 1;
                transform: none;
                transition: none;
                will-change: auto;
            }
        }

    </style>

</head>

