    <script>
        // Slideshow foto kegiatan volunteer pada bagian Dampak dan Pengalaman.
        // Berjalan otomatis tanpa tombol panah atau kontrol manual.
        (() => {
            const gallery = document.querySelector('.impact-art');
            if (!gallery) return;

            const slides = Array.from(gallery.querySelectorAll('.impact-slide'));
            if (slides.length < 2) return;

            let current = 0;
            window.setInterval(() => {
                const next = (current + 1) % slides.length;
                slides[next].classList.add('is-active');
                slides[current].classList.remove('is-active');
                current = next;
            }, 5000);
        })();

        (() => {
            const section = document.querySelector('.about-section');
            if (!section) return;

            const slides = Array.from(section.querySelectorAll('.about-slides img'));
            if (slides.length < 2) return;

            let current = 0;
            let timerStarted = false;

            // Semua foto sudah tertanam di file Blade, jadi tidak perlu folder gambar terpisah.
            slides.forEach((img) => {
                img.loading = 'eager';
                img.decoding = 'async';
            });

            const startSlideshow = () => {
                if (timerStarted) return;
                timerStarted = true;

                window.setInterval(() => {
                    const next = (current + 1) % slides.length;
                    slides[next].classList.add('is-active');
                    slides[current].classList.remove('is-active');
                    current = next;
                }, 3500);
            };

            // Mulai begitu foto pertama siap; foto berikutnya sudah ikut dimuat sejak awal.
            if (slides[0].complete && slides[0].naturalWidth > 0) {
                startSlideshow();
            } else {
                slides[0].addEventListener('load', startSlideshow, { once: true });
                slides[0].addEventListener('error', startSlideshow, { once: true });
            }
        })();
    
        // Efek scroll reveal: elemen muncul halus ketika mulai terlihat di layar.
        (() => {
            const revealSelectors = [
                '.landing-section .section-kicker',
                '.landing-section .section-title',
                '.landing-section .section-lead',
                '.feature-card',
                '.activity-card',
                '.activity-cta',
                '.why-card',
                '.category-item',
                '.step-card',
                '.impact-art',
                '.impact-points .impact-point',
                '.community-panel',
                '.faq-item',
                '.join-panel'
            ];

            const elements = document.querySelectorAll(revealSelectors.join(', '));
            if (!elements.length) return;

            // Beri jeda berurutan agar kartu dan poin tidak muncul bersamaan.
            const groupCounters = new Map();

            elements.forEach((element) => {
                const group = element.parentElement;
                const index = groupCounters.get(group) || 0;
                groupCounters.set(group, index + 1);

                element.classList.add('scroll-reveal');
                element.style.setProperty(
                    '--reveal-delay',
                    `${Math.min(index, 5) * 110}ms`
                );
            });

            // Jika browser tidak mendukung IntersectionObserver, tampilkan semua elemen.
            if (!('IntersectionObserver' in window)) {
                elements.forEach((element) => element.classList.add('is-visible'));
                return;
            }

            const observer = new IntersectionObserver((entries) => {
                entries.forEach((entry) => {
                    // Munculkan lagi setiap kali elemen masuk ke layar,
                    // lalu sembunyikan kembali saat keluar dari layar.
                    if (entry.isIntersecting) {
                        entry.target.classList.add('is-visible');
                    } else {
                        entry.target.classList.remove('is-visible');
                    }
                });
            }, {
                threshold: 0.12,
                rootMargin: '0px 0px -35px 0px'
            });

            elements.forEach((element) => observer.observe(element));
        })();

</script>

